1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	};
11	
12	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
13	
14	export type ScenarioResult = { premium: number };
15	
16	export type ScenarioOutcome = { results: ScenarioResult[] };
17	
18	type Item = { type: string };
19	
20	type Scenario = { steps: { items: Item[] }[] };
21	
22	const basePremiumOf = (item: Item): number =>
23	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
24	
25	// Adds the surcharge as a separate term rather than scaling by 1.1, because
26	// `100 * 1.1` is 115.00000000000001 in binary floating point.
27	const withFirstInsuranceSurcharge = (amount: number): number =>
28	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
29	
30	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
31	// customer) round up.
32	const roundPremiumInMHPCOsFavour = (amount: number): number =>
33	  Math.ceil(amount);
34	
35	const quotePremium = (items: Item[]): number => {
36	  const basePremium = items.reduce<number>(
37	    (total, item) => total + basePremiumOf(item),
38	    0,
39	  );
40	
41	  return roundPremiumInMHPCOsFavour(
42	    withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE,
43	  );
44	};
45	
46	export const runScenario = (scenario: unknown): ScenarioOutcome => {
47	  const { steps } = scenario as Scenario;
48	
49	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
50	
51	  return { results };
52	};
